#include <cuda_runtime.h>

template <int TILE_SIZE, int UNROLL_FACTOR>
__global__ void matmul_kernel(const float* A, const float* B, float* C, int N) {
    // Shared memory for tiles of A and B
    __shared__ float As[TILE_SIZE][TILE_SIZE];
    __shared__ float Bs[TILE_SIZE][TILE_SIZE];

    int row = blockIdx.y * TILE_SIZE + threadIdx.y;
    int col = blockIdx.x * TILE_SIZE + threadIdx.x;

    float sum = 0.0f;

    // Loop over tiles
    for (int t = 0; t < (N + TILE_SIZE - 1) / TILE_SIZE; ++t) {
        // Load tile of A into shared memory
        int a_col = t * TILE_SIZE + threadIdx.x;
        if (row < N && a_col < N) {
            As[threadIdx.y][threadIdx.x] = A[row * N + a_col];
        } else {
            As[threadIdx.y][threadIdx.x] = 0.0f;
        }

        // Load tile of B into shared memory
        int b_row = t * TILE_SIZE + threadIdx.y;
        if (b_row < N && col < N) {
            Bs[threadIdx.y][threadIdx.x] = B[b_row * N + col];
        } else {
            Bs[threadIdx.y][threadIdx.x] = 0.0f;
        }

        // Synchronize to ensure all tiles are loaded
        __syncthreads();

        // Compute partial dot product with loop unrolling
        for (int k = 0; k < TILE_SIZE; k += UNROLL_FACTOR) {
            sum += As[threadIdx.y][k] * Bs[k][threadIdx.x];
            sum += As[threadIdx.y][k+1] * Bs[k+1][threadIdx.x];
            sum += As[threadIdx.y][k+2] * Bs[k+2][threadIdx.x];
            sum += As[threadIdx.y][k+3] * Bs[k+3][threadIdx.x];
        }

        // Synchronize before loading next tiles
        __syncthreads();
    }

    // Write result to global memory
    if (row < N && col < N) {
        C[row * N + col] = sum;
    }
