import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# CUDA kernel for matrix multiplication with register blocking
matmul_kernel_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

template <int TILE_SIZE, int BLOCK_SIZE>
__global__ void matmul_kernel(const float* A, const float* B, float* C, int N) {
    // Shared memory for tiles of A and B
    __shared__ float As[TILE_SIZE][TILE_SIZE];
    __shared__ float Bs[TILE_SIZE][TILE_SIZE];

    // Each thread computes a BLOCK_SIZE x BLOCK_SIZE tile
    int blockRow = blockIdx.y * TILE_SIZE;
    int blockCol = blockIdx.x * TILE_SIZE;

    int threadRow = threadIdx.y * BLOCK_SIZE;
    int threadCol = threadIdx.x * BLOCK_SIZE;

    // Register storage for results
    float c[BLOCK_SIZE][BLOCK_SIZE] = {{0}};

    // Loop over tiles
    for (int t = 0; t < (N + TILE_SIZE - 1) / TILE_SIZE; ++t) {
        // Load tile of A into shared memory
        int aRow = blockRow + threadIdx.y;
        int aCol = t * TILE_SIZE + threadIdx.x;
        if (aRow < N && aCol < N) {
            As[threadIdx.y][threadIdx.x] = A[aRow * N + aCol];
        } else {
            As[threadIdx.y][threadIdx.x] = 0.0f;
        }

        // Load tile of B into shared memory
        int bRow = t * TILE_SIZE + threadIdx.y;
        int bCol = blockCol + threadIdx.x;
        if (bRow < N && bCol < N) {
            Bs[threadIdx.y][threadIdx.x] = B[bRow * N + bCol];
        } else {
            Bs[threadIdx.y][threadIdx.x] = 0.0f;
        }

        // Synchronize to ensure all tiles are loaded
        __syncthreads();

        // Compute partial dot products using register blocking
        for (int k = 0; k < TILE_SIZE; k++) {
            // Prefetch values for A and B
            float aReg[BLOCK_SIZE];
            float bReg[BLOCK_SIZE];

            // Load values from shared memory into registers
            for (int i = 0; i < BLOCK_SIZE; i++) {
                aReg[i] = As[threadIdx.y + i][k];
                bReg[i] = Bs[k][threadIdx.x + i];
            }

            // Multiply and accumulate
            for (int i = 0; i < BLOCK_SIZE; i++) {
                for (int j = 0; j < BLOCK_SIZE; j++) {
                    c[i][j] += aReg[i] * bReg[j];
                }
            }
        }

        // Synchronize before loading next tiles
        __syncthreads();
    }

    // Write result to global memory
    int globalRow, globalCol;
    for (int i = 0; i < BLOCK_SIZE; i++) {
        globalRow = blockRow + threadRow + i;
        for (int j = 0; j < BLOCK_SIZE; j++) {
            globalCol = blockCol + threadCol + j;
            if (globalRow < N && globalCol < N) {
                C[globalRow * N + globalCol] = c[i][j];
            }
        }
    }
}

torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B) {
    // Check input dimensions
    auto sizes = A.sizes();
    int N = sizes[0];
    TORCH_CHECK(A.dim() == 2 && B.dim() == 2, "Inputs must be 2D tensors");
    TORCH_CHECK(sizes[1] == N, "Inputs must be square matrices");
