    const int TILE_SIZE = 32;
    const int BLOCK_SIZE = 4;  // Each thread computes 4x4 output
    dim3 threadsPerBlock(TILE_SIZE // BLOCK_SIZE, TILE_SIZE // BLOCK_SIZE);
    dim3 blocksPerGrid((N + TILE_SIZE - 1) / TILE_SIZE,
                      (N + TILE_SIZE - 1) / TILE_SIZE);

    // Launch kernel
    matmul_kernel<TILE_SIZE, BLOCK_SIZE><<<blocksPerGrid, threadsPerBlock>>>(A.data_ptr<float>(), B.data_ptr<float>(), C.data_ptr<float>(), N);

    return C;
}
"""

